import { resultsContent } from './results-template.mjs';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const out=path.join(root,'dist');
const production=process.argv.includes('--production');
const load=n=>JSON.parse(fs.readFileSync(path.join(root,'site/content',n+'.json'),'utf8'));
const images=load('images'),forms=load('forms');
const site=load('site'),pubs=load('publications'),projects=load('projects'),people=load('people'),theses=load('theses'),posts=load('posts'),fellows=load('fellowships'),explorer=load('explorer');
fs.rmSync(out,{recursive:true,force:true});fs.mkdirSync(out,{recursive:true});fs.cpSync(path.join(root,'site/assets'),path.join(out,'assets'),{recursive:true});
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const A='<span class="arrow" aria-hidden="true">↗</span>',R='<span class="arrow" aria-hidden="true">→</span>';
let current='';
const base=()=>current==='404'?'/':current.includes('/')?'../'.repeat(current.split('/').length-1):'./';
const H=p=>base()+(p===''?'index.html':p+'.html');
const asset=p=>base()+'assets/'+p;
const canonical=p=>site.domain+'/'+p;
const ext=(u,t,cl='')=>`<a href="${E(u)}" ${cl?`class="${cl}"`:''} target="_blank" rel="noopener noreferrer">${t}${A}</a>`;
const button=(p,t,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="${H(p)}">${t}${R}</a>`;
const textLink=(p,t)=>`<a class="text-link" href="${H(p)}">${t}${R}</a>`;
const badge=(s,c='')=>`<span class="tag ${c}">${E(s)}</span>`;
const nav=[['research','Research'],['publications','Publications'],['people','People'],['supervision','Supervision'],['blog','Research summaries'],['explore','Results']];
const searchIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';
const menuIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg>';
const header=()=>`<a class="skip-link" href="#main">Skip to content</a>${production?'':'<div class="preview-strip">REVIEW EDITION · SEPTEMBER 2026 · NOT THE LIVE WEBSITE</div>'}<header class="site-header"><div class="container header-inner"><a class="brand" href="${H('')}" aria-label="IEI Lab home"><span class="brand-symbol" aria-hidden="true">iei</span><span class="brand-name">Intergroup Experiences<br>& Identity Lab<small>Ariel University · Psychology</small></span></a><nav id="main-nav" class="nav" aria-label="Main navigation">${nav.map(([p,l])=>`<a href="${H(p)}" ${current===p||(p==='blog'&&current.startsWith('blog/'))||(p==='research'&&current.startsWith('projects/'))?'aria-current="page"':''}>${l}</a>`).join('')}<a href="${H('contact')}" class="mobile-contact">Contact</a></nav><div class="header-tools"><button class="icon-btn" data-open-search aria-label="Search the website (Control or Command K)">${searchIcon}</button><button class="icon-btn menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="Open navigation menu">${menuIcon}</button></div></div></header>`;
const footer=()=>`<footer class="site-footer"><div class="container"><div class="footer-grid"><div><div class="footer-title">Intergroup Experiences<br>and Identity Lab</div><p>Department of Psychology · Ariel University<br>Directed by Dr. Maor Shani<br><span lang="he" dir="rtl">${site.hebrew}</span></p></div><div><div class="footer-label">Research</div><div class="footer-links"><a href="${H('research')}">Research & projects</a><a href="${H('publications')}">Publication library</a><a href="${H('supervision')}">Thesis supervision</a><a href="${H('explore')}">Research explorer</a><a href="${H('blog')}">Research notes</a></div></div><div><div class="footer-label">Contact</div><div class="footer-links"><a href="${H('about')}">About Maor & fellowships</a><a href="${H('join')}">Prospective students</a><a href="${H('contact')}">Contact the lab</a><a href="mailto:${site.email}">${site.email}</a><a href="${base()}feed.xml">Research notes RSS</a></div></div></div><div class="footer-bottom"><span>© 2026 IEI Lab · Department of Psychology · Ariel University</span><span><a href="${H('privacy')}">Privacy & accessibility</a> · <a href="${H('privacy')}#images">Image information</a> · <a href="${H('participate')}">Research participation</a></span></div></div></footer><dialog class="search-dialog" aria-labelledby="search-title"><div class="search-top"><h2 id="search-title">Search the lab</h2><button class="icon-btn" data-close-search aria-label="Close search">✕</button></div><div class="search-body"><label for="site-search" class="small">Research, publications, people, and thesis topics</label><input id="site-search" type="search" placeholder="Try “hope”, “long COVID”, or a name" autocomplete="off"><p class="small muted" id="search-count" aria-live="polite">Enter a name, title, or topic. Press Escape to close.</p><ul class="search-results" id="search-results"></ul></div></dialog><div class="toast" role="status" hidden></div>`;
function lens(){return `<div class="research-lens"><div class="lens-top"><span>A shared research space</span><span>01 / 03</span></div><svg viewBox="0 0 510 490" role="img" aria-label="Conceptual map connecting identity, intergroup experience, and wellbeing; not a data visualization"><defs><pattern id="grid" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#b7c5be"/></pattern></defs><rect width="510" height="490" fill="url(#grid)" opacity=".42"/><g fill="none" stroke="#9db1aa" stroke-width="1"><circle cx="260" cy="231" r="145"/><circle cx="260" cy="231" r="90" stroke-dasharray="2 7"/><path d="M95 160 255 100 404 175 365 348 152 352Z M95 160 365 348 M255 100 152 352 M404 175 152 352"/></g><circle cx="260" cy="231" r="59" fill="#172d3c"/><text x="260" y="227" fill="#f7f6f1" font-family="Georgia,serif" font-size="26" text-anchor="middle">Identity</text><text x="260" y="249" fill="#c8d9d5" font-family="Arial,sans-serif" font-size="9" text-anchor="middle" letter-spacing="1.5">IN CONTEXT</text><g fill="#426e66" stroke="#edf1ee" stroke-width="5"><circle cx="95" cy="160" r="7"/><circle cx="255" cy="100" r="7"/><circle cx="404" cy="175" r="7"/><circle cx="365" cy="348" r="7"/><circle cx="152" cy="352" r="7"/></g><g fill="#172d3c" font-family="Arial,sans-serif" font-size="12"><text x="83" y="139">Belonging</text><text x="255" y="80" text-anchor="middle">Conflict</text><text x="404" y="155" text-anchor="middle">Experience</text><text x="365" y="377" text-anchor="middle">Wellbeing</text><text x="152" y="381" text-anchor="middle">Relationships</text></g></svg><div class="lens-caption">Understanding people through the groups, relationships,<br>and social conditions that shape their lives.</div></div>`}
function graphic(kind='network'){if(kind==='hope')return `<svg viewBox="0 0 500 240" aria-hidden="true"><g fill="none" stroke="#c8d4d3"><path d="M65 195H450M65 195V40"/><path d="M65 145H450M65 95H450M65 45H450" stroke-dasharray="2 5"/></g><path d="M80 160C180 158 195 90 270 94S369 61 432 42" stroke="#245d81" stroke-width="3" fill="none"/><path d="M80 71C180 50 220 123 284 132S375 176 432 183" stroke="#426e66" stroke-width="3" fill="none"/><g fill="#245d81"><circle cx="80" cy="160" r="5"/><circle cx="270" cy="94" r="5"/><circle cx="432" cy="42" r="5"/></g><text x="76" y="224" font-family="Arial" font-size="9" fill="#52626c" letter-spacing="1.8">TWO GOALS. DIFFERENT QUESTIONS. · CONCEPTUAL ILLUSTRATION</text></svg>`;
if(kind==='profiles')return `<svg viewBox="0 0 500 240" aria-hidden="true"><g fill="#245d81"><rect x="82" y="62" width="70" height="133" rx="2"/><rect x="212" y="103" width="70" height="92" rx="2"/><rect x="342" y="76" width="70" height="119" rx="2"/></g><g stroke="#f7f6f1" stroke-width="1" opacity=".35"><path d="M82 95h70M82 128h70M82 161h70M212 136h70M212 169h70M342 109h70M342 142h70M342 175h70"/></g><text x="82" y="224" font-family="Arial" font-size="9" fill="#52626c" letter-spacing="1.8">PATTERNS WITHIN A POPULATION · CONCEPTUAL ILLUSTRATION</text></svg>`;
if(kind==='identity')return `<svg viewBox="0 0 500 240" aria-hidden="true"><g fill="none" stroke-width="1.3"><circle cx="250" cy="113" r="78" stroke="#245d81"/><circle cx="216" cy="113" r="59" stroke="#426e66"/><circle cx="280" cy="113" r="51" stroke="#8aaba1"/><path d="M82 113h91m154 0h91" stroke="#b2c3bd"/></g><circle cx="241" cy="113" r="5" fill="#245d81"/><text x="110" y="224" font-family="Arial" font-size="9" fill="#52626c" letter-spacing="1.8">A CONDITION, NOT THE WHOLE SELF · CONCEPTUAL ILLUSTRATION</text></svg>`;
return `<svg viewBox="0 0 500 240" aria-hidden="true"><g fill="none" stroke="#9bb4ab" stroke-width="1"><path d="M80 141 150 70 250 123 327 53 417 113 357 184 250 123 145 186 80 141M150 70 145 186M327 53 357 184M80 141 250 123 417 113"/></g><g fill="#426e66"><circle cx="80" cy="141" r="6"/><circle cx="150" cy="70" r="7"/><circle cx="145" cy="186" r="5"/><circle cx="327" cy="53" r="7"/><circle cx="417" cy="113" r="6"/><circle cx="357" cy="184" r="6"/></g><circle cx="250" cy="123" r="13" fill="#245d81"/><circle cx="250" cy="123" r="32" fill="none" stroke="#245d81" opacity=".3"/><text x="98" y="224" font-family="Arial" font-size="9" fill="#52626c" letter-spacing="1.8">PEOPLE IN A SOCIAL CONTEXT · CONCEPTUAL ILLUSTRATION</text></svg>`}

const postImages={
 'hope-for-what':'hope-research','living-with-antisemitism':'germany-research',
 'inclusivity-and-disagreement':'supervision','long-covid-stigma':'publications',
 'illness-and-identity':'publications','accommodating-prejudice':'germany-research',
 'reading-an-interactive-graph':'interactive-results','welcome-to-iei':'supervision'
};
const projectImages={'antisemitism-health':'germany-research','hope-conflict':'hope-research','inclusivity':'supervision','illness-identity':'publications'};
function photo(key,{link='',label='',className='',eager=false}={}){
 if(!key||!images[key])return '';
 const image=images[key];
 const img=`<img src="${asset('images/'+key+'-960.webp')}" srcset="${[480,960,1440].map(w=>asset('images/'+key+'-'+w+'.webp')+' '+w+'w').join(', ')}" sizes="(max-width:700px) 100vw, (max-width:1100px) 50vw, 620px" width="1440" height="1080" loading="${eager?'eager':'lazy'}" decoding="async" alt="${E(image.alt)} AI-generated illustration.">`;
 return `<figure class="editorial-photo ${className}">${link?`<a class="photo-link" href="${H(link)}" aria-label="${E(label)}">${img}</a>`:img}<figcaption>AI-generated illustration</figcaption></figure>`;
}
function inquiryForm(kind){
 const f=forms[kind],participation=kind==='participate';
 const hidden=Object.entries(f.hidden).map(([n,v])=>`<input type="hidden" name="${E(n)}" value="${E(v)}">`).join('');
 const topics=[['general','General inquiry'],['media','Media / press'],['student','Student / supervision'],['collab','Research collaboration'],['participate','Study participation']];
 const areas=['General research panel (Israel)','Jewish diaspora well-being & antisemitism','Student participant pool'];
 return `<form id="${kind}-inquiry" class="contact-form inquiry-form" action="${E(f.action)}" method="POST" data-provider="${E(f.provider)}" data-ajax-action="${E(f.ajaxAction)}" data-kind="${kind}" data-enabled="${production?'true':'false'}">
 <h2>${participation?'Research participation inquiry':'Send an inquiry'}</h2>
 <p class="form-explanation">${participation?'Ask about opportunities in an area of interest. This is an inquiry, not study enrollment or consent to participate.':'Use this form to send a message to the lab. You do not need an email application to submit it.'}</p>
 ${production?'':`<p class="form-preview-note" role="note"><strong>Review version.</strong> Submissions are disabled here. The production build uses the existing ${E(f.provider)} connection.</p>`}
 ${hidden}<div class="form-honeypot" aria-hidden="true"><label for="${kind}-honey">Leave this field empty</label><input type="${f.honeypotType}" name="${f.honeypot}" id="${kind}-honey" tabindex="-1" autocomplete="off"></div>
 <fieldset class="inquiry-fields" ${production?'':'disabled'}><legend class="visually-hidden">${participation?'Your research participation inquiry':'Your inquiry'}</legend>
 <div class="form-row"><div class="control"><label for="${kind}-name">${participation?'Full name':'Name'} <span class="required-label">(required)</span></label><input id="${kind}-name" name="name" autocomplete="name" required maxlength="150"></div>
 <div class="control"><label for="${kind}-email">Email <span class="required-label">(required)</span></label><input id="${kind}-email" name="email" type="email" autocomplete="email" required maxlength="254"></div></div>
 <div class="control"><label for="${kind}-topic">${participation?'Area of interest':'Topic'}</label><select id="${kind}-topic" name="${participation?'study':'topic'}">${participation?areas.map(s=>`<option value="${E(s)}">${E(s)}</option>`).join(''):topics.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>${participation?'<p class="field-help">These are areas of interest, not announcements that a particular study is recruiting.</p>':''}</div>
 <div class="control"><label for="${kind}-message">${participation?'Optional note':'Message <span class="required-label">(required)</span>'}</label><textarea id="${kind}-message" name="message" ${participation?'':'required'} maxlength="5000" rows="6" placeholder="${participation?'What research would you like to hear about?':'What would you like to discuss?'}"></textarea></div>
 <p class="form-privacy">Submitting sends your details to ${E(f.provider)} for forwarding to the lab${participation?' at its Ariel address, with a copy to its Osnabrück address':''}. Please do not include medical records, participant data, or other sensitive information. <a href="${H('privacy')}#inquiries">About inquiry handling</a>.</p>
 <button type="submit" class="button">${participation?'Submit interest':'Send message'}${R}</button></fieldset>
 <p class="form-status" data-form-status role="status" aria-live="polite" tabindex="-1">${production?'':'Nothing is sent or stored by this preview.'}</p>
 <noscript><p class="small">${production?'This form can be submitted without JavaScript. You will continue to the mail service and then return to the website.':'Submissions remain disabled in this review build.'}</p></noscript>
 <p class="form-fallback">Prefer email? <a href="mailto:${site.email}">${site.email}</a></p></form>`;
}

function intro(k,title,lead,crumb=''){const imageKey=({'publications':'publications','supervision':'supervision','join':'supervision'})[current];return `<section class="page-intro container ${imageKey?'intro-with-photo':''}"><div>${crumb?`<div class="breadcrumbs">${crumb}</div>`:''}<div class="eyebrow">${E(k)}</div><h1>${E(title)}</h1>${lead?`<p class="lead">${E(lead)}</p>`:''}</div>${imageKey?photo(imageKey,{className:'intro-photo',eager:true}):''}</section>`}
function cta(){return `<div class="container"><section class="connect-panel"><div><h2>Contact the lab</h2><p>For enquiries about thesis supervision, research collaboration, or publications, contact Dr. Maor Shani.</p></div><div class="actions">${button('contact','Contact')}</div></section></div>`}
function pubCitation(p){return `${p.authors} (${p.year}${p.forthcoming?', forthcoming':''}). ${p.title}. ${p.venue}.${p.doi?' https://doi.org/'+p.doi:''}`}
function pubRow(p,filter=false){return `<article class="publication-row" ${filter?`data-filter-item data-year="${p.year}" data-topic="${E(p.tags.join('|'))}" data-search="${E((p.title+' '+p.authors+' '+p.venue+' '+p.tags.join(' ')).toLowerCase())}"`:''} id="${E(p.id)}"><div class="year">${p.year}</div><div>${p.forthcoming?badge('Forthcoming','green'):''}<h3>${p.url?`<a href="${E(p.url)}" target="_blank" rel="noopener noreferrer">${E(p.title)}</a>`:E(p.title)}</h3><p>${E(p.authors)}</p><p><em>${E(p.venue)}</em>${p.sharedFirst?' · Shared first authorship':''}</p>${p.note?`<p class="small">${E(p.note)}</p>`:''}<div class="pub-buttons">${p.url?ext(p.url,p.doi?'Read paper':'View publication','ghost-button'):''}<button class="ghost-button" data-copy="${E(pubCitation(p))}">Copy reference</button><button class="ghost-button" data-bib="${p.id}">BibTeX</button>${p.studentCoauthor?badge('Student collaboration'):''}</div></div>${p.url?ext(p.url,'','paper-mark'):''}</article>`}
function noteCard(p){return `<article class="note-card" data-filter-item data-search="${E((p.title+' '+p.deck+' '+p.category).toLowerCase())}">${photo(postImages[p.slug],{link:'blog/'+p.slug,label:'Read: '+p.title,className:'card-photo'})}<div class="eyebrow">${E(p.category)} · ${Math.max(2,Math.ceil(p.sections.map(s=>s.text).join(' ').split(/\s+/).length/210))} min read</div><h3><a href="${H('blog/'+p.slug)}">${E(p.title)}</a></h3><p>${E(p.deck)}</p>${textLink('blog/'+p.slug,'Read summary')}</article>`}
function projectCard(p){return `<article class="project-card" data-filter-item data-topic="${E(p.topic)}" data-search="${E((p.title+' '+p.summary+' '+p.methods).toLowerCase())}"><div>${badge(p.status,'green')}</div><h3>${E(p.title)}</h3><p class="question">${E(p.question)}</p><p class="methods">${E(p.methods)}</p>${textLink('projects/'+p.id,'Project details')}</article>`}
const initials=n=>n.split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('');
function personCard(p){return `<article class="person-card" id="${p.id}"><div class="person-card-top"><div class="avatar" aria-hidden="true">${E(initials(p.name))}</div><div><h3>${E(p.name)}</h3><div class="program">${E(p.program)}<br>${E(p.institution)}</div></div></div>${badge(p.status,'green')}<h4>${E(p.topic)}</h4><p>${E(p.summary)}</p>${p.note?`<p class="small">${E(p.note)}</p>`:''}</article>`}
function director(){return `<section class="person-director"><div class="director-art"><span class="initials" aria-hidden="true">MS</span><small>Maor Shani · Lab director</small></div><div><div class="eyebrow">Lab director</div><h2>Dr. Maor Shani</h2><p><strong>Department of Psychology, Ariel University<br>Senior Lecturer from October 2026</strong></p><p>My research connects social identity, intergroup relations, and wellbeing. I study how people experience conflict and discrimination, how social environments shape belonging, and how living with a chronic condition can become part of a person’s identity.</p><p>Before joining Ariel University, I worked as a postdoctoral researcher at Osnabrück University and at the Hebrew University of Jerusalem. I am also a Research Fellow at the London Centre for the Study of Contemporary Antisemitism.</p><div class="actions">${textLink('about','Biography & fellowships')}<a class="text-link" href="mailto:${site.email}">Email Maor${A}</a></div></div></section>`}
function sourcesMarkup(sources){return sources.length?`<section class="article-sources"><h2>References</h2>${sources.map(s=>ext(s.url,E(s.label))).join('')}</section>`:''}
const pages=[];
function page(p,title,description,bodyFn,extra={}){
 current=p;const body=bodyFn();const jsonld=extra.article?{'@context':'https://schema.org','@type':'BlogPosting',headline:title,description,datePublished:site.updated,dateModified:site.updated,author:{'@type':'Organization',name:'IEI Lab'},publisher:{'@type':'Organization',name:site.name},mainEntityOfPage:canonical(p)}:{'@context':'https://schema.org','@type':'WebPage',name:title,description,url:canonical(p),isPartOf:{'@type':'WebSite',name:site.name,url:site.domain}};
 let html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>${E(title)} | IEI Lab · Maor Shani</title><meta name="description" content="${E(description)}"><meta name="robots" content="${production?'index,follow':'noindex,nofollow'}"><link rel="canonical" href="${canonical(p)}"><link rel="icon" type="image/svg+xml" href="${asset('favicon.svg')}"><link rel="alternate" type="application/rss+xml" title="IEI Lab research notes" href="${base()}feed.xml"><meta property="og:type" content="${extra.article?'article':'website'}"><meta property="og:title" content="${E(title)}"><meta property="og:description" content="${E(description)}"><meta property="og:site_name" content="IEI Lab"><meta property="og:url" content="${canonical(p)}"><meta property="og:image" content="${site.domain}/assets/social-card.png"><meta property="og:image:alt" content="Intergroup Experiences and Identity Lab, directed by Dr. Maor Shani at Ariel University"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="${asset('site.css')}"><script type="application/ld+json">${JSON.stringify(jsonld).replace(/</g,'\\u003c')}</script><script src="${asset('search-index.js')}" defer></script><script src="${asset('app.js')}" defer></script><script src="${asset('results.js')}" defer></script><script src="${asset('forms.js')}" defer></script></head><body data-mode="${production?'production':'review'}" data-base="${base()}" ${extra.article?'data-article="true"':''}>${header()}<main id="main" tabindex="-1">${body}</main>${footer()}${extra.article?'<div class="reading-progress" aria-hidden="true"></div>':''}</body></html>`;
 const target=path.join(out,p===''?'index.html':p+'.html');fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,html);pages.push({path:p,title,description,category:extra.category||(extra.article?'Research note':'Page')});
}
page('','Intergroup Experiences and Identity Lab',site.description,()=>`<section class="hero container"><div class="hero-grid"><div><div class="eyebrow">Department of Psychology · Ariel University</div><h1>Intergroup Experiences<br>and Identity Lab</h1><p class="lead">Research on social identity, intergroup relations, discrimination, and psychological wellbeing.</p><p>Directed by Dr. Maor Shani. The lab studies these topics through surveys, experiments, longitudinal research, and qualitative methods.</p><div class="actions">${button('research','Research and projects')}${textLink('publications','Publications')}</div></div><aside class="lab-info"><h2>Lab information</h2><dl><dt>Institution</dt><dd>Ariel University, Department of Psychology</dd><dt>Lab director</dt><dd>Dr. Maor Shani</dd><dt>Opening</dt><dd>October 2026</dd><dt>Contact</dt><dd><a href="mailto:${site.email}">${site.email}</a></dd></dl><a class="text-link" href="${H('join')}">Thesis supervision and collaboration${R}</a></aside></div></section><section class="feature-section"><div class="container feature-grid"><div><h2>Interactive research results</h2><p>Compare findings from the hope and antisemitism studies. The charts show published means, response distributions, and correlations, with numerical tables and source information.</p><div class="actions">${button('explore','View the results',true)}</div><div class="feature-chart"><h3>Hope before and after October 7</h3><p>Study 4 · Same participants at both waves, N = 129</p><table><caption>Adjusted means from Figure 3; scale 1–7</caption><thead><tr><th scope="col">Measure</th><th scope="col">2021</th><th scope="col">Oct. 2023</th></tr></thead><tbody><tr><th scope="row">Hope for victory</th><td>5.03</td><td>6.56</td></tr><tr><th scope="row">Hope for peace</th><td>4.99</td><td>3.56</td></tr></tbody></table><p class="source-line">${ext(explorer.study4.source,'Shani et al. (2024), Figure 3')}. The 2021 baseline was not immediately before October 7.</p></div></div><div class="feature-visual">${photo('interactive-results',{link:'explore',label:'Interactive research results',className:'results-photo'})}</div></div></section><section class="section container"><div class="section-top"><h2>Research areas</h2></div><div class="three-col"><article class="theme-card"><h3>Intergroup relations and conflict</h3><p>Political emotions, hope for peace and victory, social norms, cooperation, and coexistence.</p>${textLink('research','Related projects')}</article><article class="theme-card"><h3>Antisemitism and discrimination</h3><p>Antisemitic experiences, prejudice, coping, social participation, and psychosocial health.</p>${textLink('research','Related projects')}</article><article class="theme-card"><h3>Health and wellbeing</h3><p>Illness identity, stigma, social support, and adaptation to chronic health conditions.</p>${textLink('research','Related projects')}</article></div></section><section class="section container"><div class="section-top"><h2>Selected publications</h2>${textLink('publications','All publications')}</div>${['pnas-nexus-2026','bleed-2025','long-covid-2025'].map(id=>pubRow(pubs.find(p=>p.id===id))).join('')}</section><section class="section container" style="padding-top:20px"><div class="section-top"><h2>Research summaries</h2>${textLink('blog','All summaries')}</div><div class="three-col">${posts.slice(0,3).map(noteCard).join('')}</div></section><div class="container">${director()}</div>${cta()}`);
page('research','Research & current projects','Research programs on conflict, antisemitism, inclusion, illness identity, and wellbeing.',()=>`${intro('Research','Research areas and current projects','Our projects bring together experimental, longitudinal, qualitative, and person-centered approaches. Published findings and ongoing research are identified separately.')}<section class="container" data-filter-scope><div class="pill-row" aria-label="Filter research by area"><button class="pill" data-topic-button="" aria-pressed="true">All areas</button>${['Antisemitism','Conflict and society','Health and wellbeing'].map(s=>`<button class="pill" data-topic-button="${E(s)}" aria-pressed="false">${E(s)}</button>`).join('')}</div><p class="filter-count" data-filter-count aria-live="polite">${projects.length} projects and research programs</p><div class="two-col">${projects.map(projectCard).join('')}</div><p class="empty-state" data-empty hidden>No projects match this selection.</p><p class="source-line">Project descriptions draw on the supplied research record and ${ext('https://londonantisemitism.com/team/maor-shani/','the London Centre research profile')}. Ongoing projects do not imply open recruitment or confirmed funding beyond what is stated.</p></section>${cta()}`);
for(const p of projects)page('projects/'+p.id,p.title,p.question,()=>`${intro(p.topic,p.title,p.question,`<a href="${H('research')}">Research</a> / Project overview`)}<section class="container project-detail"><div class="prose">${photo(projectImages[p.id],{className:'article-photo',eager:true})}<p>${E(p.summary)}</p><h2>Research approach</h2><p>${E(p.methods)}. This project overview explains the research direction; it does not present unpublished estimates or participant-level data.</p>${p.outputs.length?`<h2>Related publications</h2>${p.outputs.map(id=>pubRow(pubs.find(q=>q.id===id))).join('')}`:`<div class="notice">${p.status==='Evidence synthesis in progress'?'The review is still in progress. No final study count or pooled effect is reported.':'This is ongoing work. Findings and publication details will be added after verification.'}</div>`}<div class="actions">${button('contact','Discuss a collaboration',true)}</div></div><aside class="side-note"><h3>Project information</h3><p>${badge(p.status,'green')}</p><p><strong>Area</strong><br>${E(p.topic)}</p><p><strong>Methods</strong><br>${E(p.methods)}</p><p>Looking for the people behind related thesis projects?</p>${textLink('people','Meet the students')}</aside></section>`,{category:'Project'});
page('people','People & current supervision','Meet Dr. Maor Shani and the students whose projects contribute to the research program.',()=>`${intro('People','Lab members and students','Lab director and the students developing thesis projects at Ariel University and through external supervision.')}<div class="container">${director()}<section class="section"><div class="section-top"><div><div class="eyebrow">Ariel University</div><h2>Current thesis projects</h2></div><p>Topics are described as work in progress. These are research projects, not completed findings.</p></div><div class="two-col">${people.filter(p=>p.institution==='Ariel University').map(personCard).join('')}</div></section><section class="section" style="padding-top:15px"><div class="eyebrow">Across institutions</div><h2>External supervision</h2><div class="two-col">${people.filter(p=>p.institution!=='Ariel University').map(personCard).join('')}</div></section><div class="notice">For completed projects, the supervision archive records 23 theses completed at Osnabrück University, with short topic summaries and related publications where documented.</div><div class="actions" style="margin-bottom:45px">${button('supervision','View completed theses',true)}</div></div>${cta()}`);
page('supervision','Thesis supervision archive','A searchable archive of 23 completed theses at Osnabrück University, plus current supervision at Ariel University.',()=>`${intro('Supervision','Thesis supervision','A record of completed work in social, developmental, intercultural, and health psychology. Each summary describes the thesis topic, not an unverified finding.')}<section class="container" data-filter-scope><div class="notice"><strong>Current supervision at Ariel University</strong><br>See the ${`<a href="${H('people')}">current thesis projects</a>`} for the latest research directions. The archive below contains the 23 completed Osnabrück theses recorded in the supplied CV, from 2021 to 2025.</div><div class="filter-panel"><div class="control grow"><label for="thesis-query">Search by name, topic, or title</label><input type="search" id="thesis-query" data-filter-search placeholder="For example, identity or discrimination"></div><div class="control"><label for="thesis-year">Year</label><select id="thesis-year" data-filter-year><option value="">All years</option>${[2025,2024,2023,2022,2021].map(y=>`<option>${y}</option>`).join('')}</select></div><div class="control"><label for="thesis-topic">Area</label><select id="thesis-topic" data-filter-topic><option value="">All areas</option>${['Antisemitism','Conflict and society','Health and wellbeing','Identity and inclusion'].map(t=>`<option>${E(t)}</option>`).join('')}</select></div><button class="ghost-button" data-reset-filters>Reset</button></div><p class="filter-count" data-filter-count aria-live="polite">23 completed theses</p><div class="thesis-list">${theses.map(t=>`<article class="thesis-record" id="${t.id}" data-filter-item data-year="${t.year}" data-topic="${E(t.topic)}" data-search="${E((t.name+' '+t.title+' '+t.summary+' '+t.degree).toLowerCase())}"><div class="year">${t.year}</div><div><h3>${E(t.name)} <span class="small muted">· ${E(t.degree)}</span></h3><div class="thesis-title">${E(t.title)}</div><p>${E(t.summary)}</p>${t.award?`<div class="award">Recognition · ${E(t.award)}</div>`:''}${t.publication?`<a class="text-link" href="${H('publications')}#${t.publication}">Related publication${R}</a>`:''}</div></article>`).join('')}</div><p class="empty-state" data-empty hidden>No theses match. Try another name or reset the filters.</p><p class="small muted">English titles are lightly standardized from the supplied supervision record. Topic summaries are editorial descriptions based on those titles. Full thesis texts, grades, assessments, and private student information are not distributed here.</p></section>${cta()}`);
page('publications','Publication library','Search publications by topic, year, title, or author. Read papers, copy references, and export citations.',()=>`${intro('Publication library','Publications','Find papers and chapters across our research areas. Filter the library, follow a publication to its source, or save a reference.')}<section class="container" data-filter-scope><div class="filter-panel"><div class="control grow"><label for="pub-search">Search publications</label><input type="search" id="pub-search" data-filter-search placeholder="Title, author, keyword, or journal"></div><div class="control"><label for="pub-year">Year</label><select id="pub-year" data-filter-year><option value="">All years</option>${[...new Set(pubs.map(p=>p.year))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}</select></div><div class="control"><label for="pub-topic">Keyword</label><select id="pub-topic" data-filter-topic><option value="">All keywords</option>${[...new Set(pubs.flatMap(p=>p.tags))].sort().map(t=>`<option>${E(t)}</option>`).join('')}</select></div><button class="ghost-button" data-reset-filters>Reset</button></div><p class="filter-count" data-filter-count aria-live="polite">26 publication records</p>${pubs.map(p=>pubRow(p,true)).join('')}<p class="empty-state" data-empty hidden>No publications match this search. Reset the filters to see the full library.</p><div class="notice">The library retains the supplied publication list and distinguishes forthcoming work. Some large collaborative papers use abbreviated author lists. Exported records identify this limitation; consult the publisher before using an abbreviated record in a manuscript.</div><div class="actions">${ext('https://scholar.google.com/citations?user=J0Zm7EwAAAAJ&hl=en','Google Scholar','text-link')}${ext('https://orcid.org/0000-0002-5301-5332','ORCID','text-link')}${ext('https://www.researchgate.net/profile/Maor-Shani','ResearchGate','text-link')}</div></section>${cta()}`);
page('blog','Research notes','Accessible notes on the lab’s research, methods, and work in progress.',()=>`${intro('Research notes','Research summaries','Short essays about our questions, findings, and methods. Research in progress is labeled separately from published evidence.')}<section class="container" data-filter-scope><div class="filter-panel"><div class="control grow"><label for="notes-query">Find a note</label><input id="notes-query" type="search" data-filter-search placeholder="Hope, stigma, inclusion, or methods"></div></div><p class="filter-count" data-filter-count aria-live="polite">8 research notes</p><div class="three-col">${posts.map(noteCard).join('')}</div><p class="empty-state" data-empty hidden>No research notes match.</p></section>${cta()}`);
for(const p of posts)page('blog/'+p.slug,p.title,p.deck,()=>`${intro(p.category,p.title,p.deck,`<a href="${H('blog')}">Research notes</a>`)}<div class="container article-layout"><aside class="article-meta"><p><strong>IEI Lab</strong><br>Research notes<br>8 September 2026</p><p>${Math.max(2,Math.ceil(p.sections.map(s=>s.text).join(' ').split(/\s+/).length/210))} minute read</p><a href="${H('blog')}">All notes</a><button class="ghost-button" data-copy="${canonical('blog/'+p.slug)}">Copy article link</button></aside><article class="prose">${photo(postImages[p.slug],{className:'article-photo',eager:true})}${p.category==='Research in progress'?'<div class="notice">Research in progress: this note explains a research question and does not report settled findings.</div>':''}${p.sections.map(s=>`<section><h2>${E(s.heading)}</h2><p>${E(s.text)}</p></section>`).join('')}${sourcesMarkup(p.sources)}${p.related?`<div class="notice">Explore this idea in the <a href="${H('explore')}#${p.related}">interactive research explorer</a>.</div>`:''}<div class="actions">${textLink('blog','Back to all research notes')}</div></article></div>`,{article:true});
function embeddedExplorer(){return `<script type="application/json" id="explorer-data">${JSON.stringify(explorer).replace(/</g,'\\u003c')}</script>`}
function hopeTable(){return `<div class="table-wrap"><table id="hope-table"><caption>Selected published Pearson correlations from Table 1</caption><thead><tr><th scope="col">Outcome</th><th scope="col">Hope for peace</th><th scope="col">Hope for victory</th></tr></thead><tbody>${explorer.hope.outcomes.map((o,i)=>`<tr><th scope="row">${E(o)}</th><td>${explorer.hope.studies[0].peace[i].toFixed(2)}</td><td>${explorer.hope.studies[0].victory[i].toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`}
page('explore','Interactive research results','Published findings from Study 4 of the hope paper and the survey of antisemitism and psychosocial health among Jews in Germany.',()=>`${intro('Published findings','Interactive research results','Explore the main results of the hope and antisemitism papers. Each display identifies its sample, statistical measure, and source. No participant-level data are published here.')}<div class="container">${resultsContent(explorer)}<section class="additional-heading"><h2>Additional results and methods</h2><p>The earlier study correlations, profile results, and synthetic demonstration remain available below.</p></section><details class="additional-results"><summary>Additional results: hope in Studies 1 and 2</summary><section class="explorer-block" id="earlier-hope"><div class="explorer-header"><div><div class="eyebrow">Additional published findings</div><h2>Hope correlations in Studies 1 and 2</h2><p>Compare hope for peace and hope for victory in their associations with conflict-related attitudes. These are bivariate correlations, not adjusted regression coefficients.</p></div>${badge('Published summaries','green')}</div><div class="explorer-grid"><aside class="explorer-controls"><div class="control"><label for="hope-study">Study context</label><select id="hope-study">${explorer.hope.studies.map((s,i)=>`<option value="${i}">${E(s.label)}</option>`).join('')}</select></div><div class="control"><label for="hope-outcome">Outcome</label><select id="hope-outcome">${explorer.hope.outcomes.map((s,i)=>`<option value="${i}">${E(s)}</option>`).join('')}</select></div><p><strong>Pearson’s r</strong> ranges from −1 to +1. The sign indicates direction; the magnitude indicates the strength of a linear association.</p><button class="button secondary" data-download="hope-csv">Download displayed study · CSV</button><button class="button secondary" data-download="hope-svg">Save chart · SVG</button></aside><div class="chart-panel"><h3 class="chart-title" id="hope-title">Support for compromise</h3><p class="chart-subtitle" id="hope-subtitle">Study 1 · Israeli Jews</p><div class="legend"><span>Hope for peace</span><span>Hope for victory</span></div><svg id="hope-chart" viewBox="0 0 650 225" role="img" aria-label="Published correlations for hope and support for compromise"></svg><p class="data-note" id="hope-note" aria-live="polite"></p>${hopeTable()}<p class="source-line">Source: ${ext(explorer.hope.source,explorer.hope.sourceLocation)}. Selected results, rounded as published. Study 1’s Table 1 sample-size note is inconsistent with the reported sample size elsewhere; exact pairwise sample sizes are not assumed and no confidence intervals are reconstructed.</p></div></div></section></details><details class="additional-results"><summary>Additional results: antisemitism and identity profiles</summary><section class="explorer-block" id="profiles"><div class="explorer-header"><div><div class="eyebrow">Additional published findings</div><h2>Antisemitism and identity profiles</h2><p>Explore reported mean outcomes across the three profiles in the German Jewish survey. The profile analysis used 344 complete cases out of 420 respondents.</p></div>${badge('Published summaries','green')}</div><div class="explorer-grid"><aside class="explorer-controls"><div class="control"><label for="profile-outcome">Outcome to compare</label><select id="profile-outcome">${explorer.profiles.outcomes.map((s,i)=>`<option value="${i}">${E(s.name)}</option>`).join('')}</select></div><label class="checkbox"><input id="profile-sd" type="checkbox">Show ±1 standard deviation</label><p style="margin-top:20px">Whiskers describe variation within profiles. They are <strong>not confidence intervals</strong> and are not significance tests.</p><p><strong>Data collection</strong><br>December 2022–March 2023, before October 7, 2023.</p><button class="button secondary" data-download="profile-csv">Download published summaries · CSV</button><button class="button secondary" data-download="profile-svg">Save chart · SVG</button></aside><div class="chart-panel"><h3 class="chart-title" id="profile-title">Subjective wellbeing across profiles</h3><p class="chart-subtitle">Reported mean scores · Nonprobability sample · Cross-sectional study</p><svg id="profile-chart" viewBox="0 0 650 270" role="img" aria-label="Mean subjective wellbeing in the three profiles"></svg><div class="profile-shares" aria-label="Profile sizes: 181, 29, and 134 complete cases">${explorer.profiles.groups.map(g=>`<span style="width:${g.n/344*100}%" title="${E(g.name)}: ${g.n}"></span>`).join('')}</div><div class="table-wrap"><table id="profile-table"><caption>Published profile-level descriptive statistics</caption><thead><tr><th scope="col">Profile</th><th scope="col">n</th><th scope="col">Mean</th><th scope="col">SD</th></tr></thead><tbody>${explorer.profiles.groups.map((g,i)=>`<tr><th scope="row">${E(g.name)}</th><td>${g.n}</td><td>${explorer.profiles.outcomes[0].means[i].toFixed(2)}</td><td>${explorer.profiles.outcomes[0].sd[i].toFixed(2)}</td></tr>`).join('')}</tbody></table></div><p class="data-note"><strong>Profiles are patterns, not diagnoses.</strong> They are not population prevalence estimates or fixed types of Jewish people. This display does not classify visitors. Scores on different outcome measures should not be compared directly.</p><p class="source-line">Source: ${ext(explorer.profiles.source,explorer.profiles.sourceLocation)}. Means and standard deviations are reproduced as reported; no inferential statistics are recalculated.</p></div></div></section></details><details class="additional-results"><summary>Methods demonstration: synthetic correlations</summary><section class="explorer-block" id="sandbox"><div class="explorer-header"><div><div class="eyebrow">Methods demonstration</div><h2>Synthetic correlation demonstration</h2><p>Move the slider to explore a linear association. Every point below is generated for this demonstration. It does not represent a participant or a result from the lab.</p></div>${badge('Synthetic demonstration','blue')}</div><div class="explorer-grid"><aside class="explorer-controls"><label for="correlation-range">Choose a target correlation</label><div class="slider-readout" id="r-readout">r = 0.50</div><input class="range" id="correlation-range" type="range" min="-95" max="95" step="1" value="50"><div class="control" style="margin-top:22px"><label for="sandbox-n">Number of synthetic points</label><select id="sandbox-n"><option>50</option><option selected>150</option><option>400</option></select></div><button class="button secondary" id="regenerate">Generate another example</button><p style="margin-top:18px">The generated sample is standardized and orthogonalized so that its sample correlation matches the selected target, up to numerical precision.</p></aside><div class="chart-panel"><h3 class="chart-title">A mathematical example, not research data</h3><p class="chart-subtitle" id="sandbox-summary" aria-live="polite">150 synthetic points</p><svg id="sandbox-chart" viewBox="0 0 650 380" role="img" aria-label="Synthetic correlation demonstration"></svg><p class="data-note">There is no substantive meaning to X or Y in this demonstration. A stronger correlation does not establish causality, and a weak linear correlation does not rule out a nonlinear relationship.</p></div></div></section></details>${embeddedExplorer()}</div>`);
page('about','About Maor Shani & fellowships','Academic background, research affiliations, and fellowships of Dr. Maor Shani.',()=>`${intro('About the director','Maor Shani, PhD','A research program connecting social identity, intergroup relations, and psychological wellbeing.')}<div class="container"><div class="intro-split"><div class="prose"><p>Maor Shani directs the Intergroup Experiences and Identity Lab, which begins its work at Ariel University in October 2026. His research examines conflict and reconciliation, antisemitism and discrimination, and psychological life with chronic conditions.</p><p>He was a postdoctoral researcher in developmental psychology at Osnabrück University from 2020 to 2025, following postdoctoral work in the Psychology of Intergroup Conflict and Reconciliation Lab at the Hebrew University of Jerusalem with Prof. Eran Halperin in 2019–2020.</p><p>He completed his PhD in psychology at the Bremen International Graduate School of Social Sciences in 2016, supervised by Prof. Klaus Boehnke. His dissertation examined Jewish–Palestinian coexistence and mixed-model intergroup encounters. He previously completed an MA in Integrated Social Sciences at Jacobs University Bremen and a BA in Sociology and Anthropology at the Hebrew University of Jerusalem.</p><p>His teaching and supervision connect substantive psychological questions with research design, measurement, and data analysis. The supervision archive documents completed theses at Osnabrück, while current projects continue at Ariel University and through external supervision.</p></div><aside class="side-note"><h3>Academic profiles</h3><div class="footer-links">${ext('https://scholar.google.com/citations?user=J0Zm7EwAAAAJ&hl=en','Google Scholar')}${ext('https://orcid.org/0000-0002-5301-5332','ORCID')}${ext('https://www.researchgate.net/profile/Maor-Shani','ResearchGate')}${ext('https://londonantisemitism.com/team/maor-shani/','London Centre profile')}</div><p style="margin-top:22px"><strong>Contact</strong><br><a href="mailto:${site.email}">${site.email}</a></p><p>Hebrew · English · German</p></aside></div><section class="section" id="fellowships"><div class="eyebrow">Affiliations & support</div><h2>Fellowships and scholarships</h2>${fellows.map(f=>`<article class="fellowship-row"><div class="period">${E(f.period)}</div><div><h3>${E(f.title)}</h3><p><strong>${E(f.role)}</strong></p><p>${E(f.detail)}</p>${f.url?ext(f.url,'Institutional profile','text-link'):''}</div></article>`).join('')}<p class="small muted">Historical awards are identified by their dates. Institutional profile links document affiliations and may contain older biographical details. Award amounts are omitted.</p></section><section style="padding-bottom:45px"><div class="eyebrow">Research support</div><h2>Selected funded collaborations</h2><div class="two-col"><article class="project-card"><h3>INCLUSIVITY</h3><p>Volkswagen Foundation support for research on inclusivity norms and polarization. Maor Shani served as Project Leader / Co-PI, with Prof. Maarten van Zalk as lead investigator. Related publications and analyses continue following the funded period.</p>${textLink('projects/inclusivity','Explore the research')}</article><article class="project-card"><h3>Civilian firearm decision-making</h3><p>Research supported by the Israeli Ministry of Innovation, Science and Technology. Maor Shani is Co-PI, with Prof. Uzi Ben Shalom as lead investigator and Dr. Vered Ne’eman-Haviv as Co-PI.</p>${textLink('projects/gun-culture','Explore the research')}</article></div></section></div>${cta()}`);
page('join','Prospective students & collaborators','An invitation to discuss thesis research and collaboration with the IEI Lab.',()=>`${intro('Study with us','Prospective students and collaborators','We welcome inquiries from students and collaborators interested in identity, intergroup relations, discrimination, or health psychology.')}<div class="container project-detail"><div class="prose"><h2>For prospective thesis students</h2><p>A good first message explains the question you would like to investigate, why it matters to you, and how it connects with the lab’s work. Include your degree program, relevant research experience, and the stage you have reached in planning a thesis.</p><p>Reading a related paper or a completed thesis topic can help you make the connection specific. A fully developed proposal is not required for an initial inquiry, but a focused question is more useful than a general statement of interest.</p><h2>For research collaborators</h2><p>We are interested in conversations that connect substantive questions with thoughtful methods. These may concern joint studies, measurement, comparative research, evidence synthesis, or making findings useful beyond an academic audience.</p><div class="notice">An invitation to inquire is not an advertised vacancy or a promise of supervision, funding, admission, or employment. Formal arrangements depend on the relevant university program and confirmed project capacity.</div><div class="actions">${button('contact','Start a conversation')}</div></div><aside class="side-note"><h3>Before you write</h3><p>Explore a research area, browse the publication library, and see the kinds of questions students have pursued.</p><div class="footer-links"><a href="${H('research')}">Research areas</a><a href="${H('supervision')}">Completed theses</a><a href="${H('people')}">Current supervision</a></div></aside></div>`);
page('participate','Research participation','Information and inquiries about research participation.',()=>`${intro('Research participation','Research participation','Contact the lab about areas of research that interest you.')}<section class="container contact-grid"><div class="prose"><h2>Study-specific invitations</h2><p>Any invitation to a study should identify eligibility criteria, tasks, time commitment, contact details, consent procedures, and any compensation.</p><h2>General inquiries</h2><p>The form lets you ask about research participation. It does not enroll you in a study or imply that a particular project is currently recruiting. Research consent is obtained separately for each study.</p><div class="notice">Do not send medical histories, identification documents, or other sensitive information here. This is not a research questionnaire.</div></div>${inquiryForm('participate')}</section>`);
page('contact','Contact the lab','Contact Dr. Maor Shani about research, supervision, or collaboration.',()=>`${intro('Contact','Contact','For research collaborations, thesis inquiries, speaking invitations, or questions about a publication.')}<section class="container contact-grid"><div><div class="eyebrow">Email</div><a class="email-link" href="mailto:${site.email}">${site.email}</a><p class="muted" style="margin-top:25px">Dr. Maor Shani<br>Department of Psychology<br>Ariel University</p><div class="actions"><button class="ghost-button" data-copy="${site.email}">Copy email address</button></div><div class="notice">This is an academic contact, not a clinical or emergency service. Please avoid sending confidential participant data or personal medical information.</div></div>${inquiryForm('contact')}</section>`);
page('privacy','Privacy & accessibility','How this website handles interactions, published research summaries, privacy, and accessibility.',()=>`${intro('Site information','Privacy and accessibility','A public research website should be clear about what it does and what it does not collect.')}<section class="container prose" style="margin-bottom:65px"><h2>No research responses are collected here</h2><p>The site’s code does not use advertising trackers, analytics scripts, tracking cookies, or local-storage profiles. Search, filters, and visualizations run in your browser. The contact and participation forms use external mail services as described below. The review build disables submissions.</p><p>The hosting provider may process ordinary request information to deliver and secure the website. Following an external link or sending an email involves the policies of that external service or institution. The statement above concerns this website’s code, not a promise that internet hosting produces no logs.</p><h2 id="inquiries">Contact and participation inquiries</h2><p>On the published website, the contact form submits your name, email address, selected topic, and message to Web3Forms. The research-participation inquiry uses FormSubmit and forwards the inquiry to the lab’s Ariel University address, with a copy to its Osnabrück University address. These services process submissions under their own policies; the website does not promise that they keep no records. Inquiry messages are distinct from research responses and consent.</p><p>Submitting the form is a request for a reply, not a subscription to a mailing list or enrollment in a study. Please avoid confidential or sensitive personal information. The code does not save draft messages to browser storage. ${ext('https://web3forms.com/privacy','Web3Forms privacy policy')} · ${ext('https://formsubmit.co/privacy.pdf','FormSubmit privacy policy')}.</p><h2>Research data and the explorer</h2><p>Empirical visualizations use summary statistics already reported in the linked publications. Individual participant records, private interviews, contact lists, and identifiable student documents are not included. Synthetic points in the methods sandbox are labeled as demonstrations. Exploratory displays do not constitute a psychological assessment.</p><h2 id="images">Illustrative images</h2><p>The editorial images on this website were generated with AI. They are not photographs of the lab, its staff, students, study participants, or actual research settings. Any charts within those images are illustrative and do not report findings. Actual research results appear only in the labeled interactive charts and tables with their cited sources.</p><h2>Accessibility</h2><p>The site provides keyboard navigation, visible focus indicators, labeled controls, a skip link, text alternatives for substantive graphics, and numerical tables alongside empirical charts. Motion respects reduced-motion preferences. These features are designed to support accessibility, but are not a claim of certified conformance.</p><h2>Corrections and access requests</h2><p>To report an accessibility problem or an error in a research or supervision entry, email <a href="mailto:${site.email}">${site.email}</a>. Please identify the page and describe the issue without including sensitive personal information.</p><h2>Sources and research status</h2><p>Research notes link to the relevant papers. Project descriptions distinguish ongoing work from published evidence. Statistical displays retain the limitations of their source studies; interactivity does not remove uncertainty or establish causation. Publication details and supervision status should be reviewed periodically as the research record develops.</p></section>`);
page('404','Page not found','The requested page could not be found.',()=>`${intro('Page not found','Page not found','The address may have changed. Search the site or return to the home page.')}<div class="container actions" style="margin-bottom:100px">${button('','Return home')}<button class="button secondary" data-open-search>Search the site</button></div>`);
// Browser-readable search index avoids network fetches, so the review works from a local folder.
const index=[...pages.filter(p=>p.path!=='404').map(p=>({title:p.title,description:p.description,url:p.path===''?'index.html':p.path+'.html',category:p.category})),...people.map(p=>({title:p.name,description:p.topic+' '+p.summary,url:'people.html#'+p.id,category:'Person'})),...theses.map(t=>({title:t.name+' · '+t.title,description:t.summary,url:'supervision.html#'+t.id,category:'Thesis'})),...pubs.map(p=>({title:p.title,description:p.authors+' '+p.venue,url:'publications.html#'+p.id,category:'Publication'}))];
fs.writeFileSync(path.join(out,'assets/search-index.js'),'window.IEI_SEARCH = '+JSON.stringify(index).replace(/</g,'\\u003c')+';\nwindow.IEI_PUBLICATIONS = '+JSON.stringify(pubs).replace(/</g,'\\u003c')+';');
const xml=s=>String(s).replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
fs.writeFileSync(path.join(out,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+pages.filter(p=>p.path!=='404').map(p=>`<url><loc>${canonical(p.path)}</loc><lastmod>${site.updated}</lastmod></url>`).join('')+'</urlset>');
fs.writeFileSync(path.join(out,'robots.txt'),production?`User-agent: *\nAllow: /\nSitemap: ${site.domain}/sitemap.xml\n`:'User-agent: *\nDisallow: /\n');
fs.writeFileSync(path.join(out,'feed.xml'),`<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>IEI Lab research notes</title><link>${site.domain}/blog</link><description>Research, methods, and ideas from the Intergroup Experiences and Identity Lab.</description><language>en</language>${posts.map(p=>`<item><title>${xml(p.title)}</title><link>${canonical('blog/'+p.slug)}</link><guid>${canonical('blog/'+p.slug)}</guid><description>${xml(p.deck)}</description><pubDate>Tue, 08 Sep 2026 09:00:00 GMT</pubDate></item>`).join('')}</channel></rss>`);
fs.mkdirSync(path.join(root,'review'),{recursive:true});
fs.writeFileSync(path.join(root,'review/build-manifest.json'),JSON.stringify({mode:production?'production':'review',pages:pages.length,publications:pubs.length,completedTheses:theses.length,people:people.length,projects:projects.length,posts:posts.length,paths:pages.map(p=>p.path)},null,2));
console.log(`Built ${pages.length} pages (${production?'PRODUCTION':'REVIEW / noindex'}) to ${out}.`);
